using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ActorInspectorOperations
{
    private readonly ActorPropertyBatchOperations _batch=new();private readonly Expression _equal=Equality();private static Expression Equality(){var expression=new Expression();expression.Parse("a == b",new[]{"a","b"});return expression;}
    public bool same_value(Variant a,Variant b)=>a.VariantType==b.VariantType&&_equal.Execute(new GArray{a,b}).AsBool();
    public void add_property(Control owner,Resource property,Resource definition,VBoxContainer parent)
    {
        if(owner.Call("_add_special_property",property,definition,parent).AsBool())return;var actor=Ui<Resource>(owner,"_actor");var key=property.Get("id").AsStringName();var value=_data.get_value(actor,key,default);var options=property.Get("options").AsGodotDictionary();if(property.Get("object_type").AsString().Length>0){owner.Call("_add_object_reference",property,definition,parent);return;}var heading=new HBoxContainer();parent.AddChild(heading);heading.AddChild(new Label{Text=property.Get("label").AsString(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,TooltipText=options.GetValueOrDefault("tooltip",property.Get("label")).AsString()});var reset=new Button{Name=key+"_reset",Text="↺"};add_keyframe_button(owner,heading,actor,property,new[]{key.ToString()},default);Variant Default()=>_properties.create_default_for_actor(property,actor);reset.TooltipText="Reset to default: "+Default();reset.Visible=!same_value(value,Default());heading.AddChild(reset);var batch=Ui<RefCounted>(owner,"property_batch");void Commit(Variant updated){if(!owner.Get("_syncing").AsBool())_batch.edit(batch,actor,key,updated);}reset.Pressed+=()=>{_batch.edit(batch,actor,key,Default());if(options.GetValueOrDefault("refresh_inspector",false).AsBool())owner.CallDeferred("_rebuild_selected");};var updaters=owner.Get("_updaters").AsGodotArray();updaters.Add(Callable.From(()=>{reset.Visible=!same_value(_data.get_value(actor,key,default),Default());reset.TooltipText="Reset to default: "+Default();}));if(options.ContainsKey("choices")){var choose=choice_editor(parent,property,value.AsInt32());choose.ItemSelected+=index=>{Commit(index);if(options.GetValueOrDefault("refresh_inspector",false).AsBool())owner.CallDeferred("_rebuild_selected");};updaters.Add(Callable.From(()=>choose.Select(_data.get_value(actor,key,default).AsInt32())));return;}
        void Wire(SpinBox input,Func<double,Variant> makeValue){Variant origin=value;input.Connect("interaction_started",Callable.From(()=>origin=_data.copy_value(_data.get_value(actor,key,default))));input.Connect("preview_changed",Callable.From<double>(n=>_batch.preview(batch,actor,key,makeValue(n))));input.Connect("drag_committed",Callable.From<double>(n=>_batch.finish(batch,actor,key,origin,makeValue(n))));input.Connect("drag_cancelled",Callable.From(()=>_batch.preview(batch,actor,key,origin)));input.ValueChanged+=n=>Commit(makeValue(n));}
        switch((Variant.Type)property.Get("value_type").AsInt32()){
        case Variant.Type.Vector2:case Variant.Type.Vector3:int count=property.Get("value_type").AsInt32()==(int)Variant.Type.Vector3?3:2;var state=Ui<Resource>(owner,"ui_state");string id=actor.Get("id").AsString();var link=new Button{Name=key+"_link",Text="🔗",ToggleMode=true,ButtonPressed=_state.vector_linked(state,id,key),TooltipText="Link components: changing one sets all to the same value"};heading.AddChild(link);link.Toggled+=enabled=>_state.set_vector_linked(state,id,key,enabled);for(int i=0;i<count;i++){int axis=i;var row=new HBoxContainer();parent.AddChild(row);row.AddChild(new Label{Text=new[]{"X","Y","Z"}[axis],Modulate=new Color(new[]{"ee9e9e","9ed8b5","99bce8"}[axis])});var input=number(owner,ActorAnimationOperations.Component(value,axis).AsDouble(),options.GetValueOrDefault("step",.01).AsDouble());input.Name=key+"_"+axis;row.AddChild(input);Wire(input,n=>{var updated=_data.get_value(actor,key,default);if(link.ButtonPressed){for(int component=0;component<count;component++)updated=ActorAnimationOperations.WithComponent(updated,component,n);}else updated=ActorAnimationOperations.WithComponent(updated,axis,n);return updated;});updaters.Add(Callable.From(()=>input.SetValueNoSignal(ActorAnimationOperations.Component(_data.get_value(actor,key,default),axis).AsDouble())));}break;
        case Variant.Type.Float:case Variant.Type.Int:var numeric=number_editor(owner,parent,value.AsDouble(),property);numeric.Name=key.ToString();Wire(numeric,n=>property.Get("value_type").AsInt32()==(int)Variant.Type.Int?Variant.From((long)n):Variant.From(n));updaters.Add(Callable.From(()=>set_number_silent(numeric,_data.get_value(actor,key,default).AsDouble())));break;
        case Variant.Type.Bool:var toggle=new CheckButton{Name=key.ToString(),ButtonPressed=value.AsBool()};parent.AddChild(toggle);toggle.Toggled+=n=>Commit(n);updaters.Add(Callable.From(()=>toggle.SetPressedNoSignal(_data.get_value(actor,key,default).AsBool())));break;
        case Variant.Type.String:case Variant.Type.StringName:var textRow=new HBoxContainer();parent.AddChild(textRow);if(options.GetValueOrDefault("file_picker",false).AsBool()){owner.Call("_add_property_file_slot",textRow,property,actor,definition);break;}var text=new LineEdit{Name=key.ToString(),Text=value.ToString(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,TooltipText=value.ToString()};textRow.AddChild(text);Variant typingOrigin=_data.copy_value(value);bool active=false;Variant TextValue()=>property.Get("value_type").AsInt32()==(int)Variant.Type.StringName?Variant.From(new StringName(text.Text)):Variant.From(text.Text);text.FocusEntered+=()=>{typingOrigin=_data.copy_value(_data.get_value(actor,key,default));active=true;};text.TextChanged+=_=>{if(owner.Get("_syncing").AsBool())return;if(!active){typingOrigin=_data.copy_value(_data.get_value(actor,key,default));active=true;}_batch.preview(batch,actor,key,TextValue());};void Submit(){if(!active)return;active=false;_batch.finish(batch,actor,key,typingOrigin,TextValue());}text.TextSubmitted+=_=>Submit();text.FocusExited+=Submit;updaters.Add(Callable.From(()=>{if(!text.HasFocus())text.Text=_data.get_value(actor,key,default).ToString();text.TooltipText=text.Text;}));break;
        case Variant.Type.Color:var color=new LiveColorPickerButton();color.Name=key.ToString();color.Color=value.AsColor();parent.AddChild(color);color.Connect("interaction_started",Callable.From(()=>Hint(owner,color,"Esc cancels color drag")));color.Connect("interaction_ended",Callable.From(()=>Hint(owner,color,"")));color.Connect("preview_changed",Callable.From<Color>(updated=>_batch.preview(batch,actor,key,updated)));color.Connect("drag_committed",Callable.From<Color,Color>((original,updated)=>_batch.finish(batch,actor,key,original,updated)));color.Connect("drag_cancelled",Callable.From<Color>(original=>_batch.preview(batch,actor,key,original)));updaters.Add(Callable.From(()=>color.Call("set_color_silent",_data.get_value(actor,key,default))));break;
        default:add_label(parent,"No editor for this property type yet.");break;}
    }
}
